package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	n := nextInt(scanner)
	k := nextInt(scanner)

	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = nextInt(scanner)
	}

	lim := a[k-1]
	ans := 0
	for _, val := range a {
		if val > 0 && val >= lim {
			ans++
		}
	}

	fmt.Print(ans)
}

func nextInt(scanner *bufio.Scanner) int {
	scanner.Scan()
	x := 0
	for _, c := range scanner.Bytes() {
		x = x*10 + int(c-'0')
	}
	return x
}

